final class LamportClock {
    private long time = 0;
    synchronized long tick() { return ++time; }   // sự kiện cục bộ hoặc gửi
    synchronized long onReceive(long remote) {
        time = Math.max(time, remote) + 1;
        return time;
    }
}

var A = new LamportClock(); var B = new LamportClock(); var C = new LamportClock();
A.tick();                       // sự kiện cục bộ của A
long aSend = A.tick();          // A gửi cho B
B.tick(); B.tick(); B.tick();   // ba sự kiện cục bộ của B
long bRecv = B.onReceive(aSend);
long bSend = B.tick();          // B gửi cho C
long cRecv = C.onReceive(bSend);
System.out.println("aSend=" + aSend + " bRecv=" + bRecv + " bSend=" + bSend + " cRecv=" + cRecv);
